"""RoboPaint: camera-calibrated, individual pressure-controlled brush sweeps."""
import sys,os,json,time,numpy as np
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
from PIL import Image
ROOT='/app/output'
class Painter:
 def __init__(self):
  self.r=Robot();self.o=self.r.get_obs(cameras=[]);self.pos=self.o.group('tcp_pose',now=True)[:3];self.rows=[];self.color=None
 def move(self,p,t=None,speed=.12):
  p=np.array(p);n=max(1,int(np.ceil((np.linalg.norm(p-self.pos)/speed if t is None else t)/.05)))
  for a in np.linspace(0,1,n+1)[1:]:self.rows.append([*(self.pos*(1-a)+p*a),0,1,0,0])
  self.pos=p
 def flush(self,cams=[]):
  while self.rows:
   a=self.rows[:195];self.rows=self.rows[195:]
   before=self.r.status()
   try:o=self.r.submit('ee_pose',a,dt=.05,cameras=cams,video='none')
   except Exception:
    self.r.wait_ready();after=self.r.status()
    if after['calls']==before['calls']:o=self.r.submit('ee_pose',a,dt=.05,cameras=cams,video='none')
    else:o=self.r.get_obs(cameras=cams)
   with open(ROOT+'/execution.jsonl','a') as f:f.write(json.dumps({'target_rows':a,'meta':o.meta})+'\n')
   if o.stopped or o.done:raise RuntimeError(str(o.meta))
  self.o=o;return o
 def dip(self,c):
  self.move([*self.pos[:2],.065]);j=c%6;row=c//6
  x=-.155+.022*j;y=.137+.022*row
  # the final row has only four wells, centred along x
  if row==2:x=-.133+.022*j
  self.move([x,y,.065]);self.move([x,y,.024],speed=.055);self.move([x,y,.024],t=.25);self.move([x,y,.065],speed=.07);self.color=c
 def sweep(self,uv0,uv1,depth=.006,speed=.035,practice=False):
  def point(uv,z):return [-.1+(.5-uv[1])* .227185,( -.1856 if practice else 0)+(.5-uv[0])*(.099393 if practice else .227185),z]
  a=point(uv0,.035);b=point(uv1,.0202-depth)
  self.move([*self.pos[:2],max(.038,self.pos[2])]);self.move(a);self.move(point(uv0,.0202-depth),speed=.035);self.move(point(uv0,.0202-depth),t=.15);self.move(b,speed=speed);self.move(b,t=.12);self.move([*b[:2],.038],speed=.04)
 def park(self):self.move([*self.pos[:2],.07]);self.move([-.30,0,.18]);self.flush()
 def photo(self,name,cams=['canvas_cam']):
  o=self.r.get_obs(cameras=cams)
  for c,im in o.last.items():Image.fromarray(im).save(ROOT+'/'+name+'_'+c+'.png')
  return o
if __name__=='__main__' and len(sys.argv)>1 and sys.argv[1]=='practice':
