 for i,depth in enumerate([.001,.003,.006,.009,.012]):
  p.sweep([.23,.13+i*.17],[.77,.13+i*.17],depth=depth,practice=True);p.flush()
 p.park();p.photo('widths',['practice_cam']);print(p.r.status())
