def rgb2lab(a):
 a=np.asarray(a)/255.;a=np.where(a>.04045,((a+.055)/1.055)**2.4,a/12.92)
 a=a@np.array([[.4124564,.3575761,.1804375],[.2126729,.7151522,.072175],[.0193339,.119192,.9503041]]).T/np.array([.95047,1,1.08883])
