  Stroke best;best.gain=-1e30;
  for(int j=0;j<6000;j++){
   int ix=rng()%(N*N);if(j%3)for(int k=0;k<5;k++){int t=rng()%(N*N);if(errv[t]>errv[ix])ix=t;}
   Stroke s; s.x=ix%N;s.y=ix/N;s.ang=(rng()%12)*M_PI/12;s.w=widths[(it<100)?3:rng()%4];
